     1	/**
     2	 * Structured logging module for the Knowledge Base application.
     3	 *
     4	 * Provides log levels, timestamps, and structured JSON output for
     5	 * all services. Replaces raw console.log calls with consistent,
     6	 * machine-parseable log entries.
     7	 */
     8	
     9	export enum LogLevel {
    10	  DEBUG = 'DEBUG',
    11	  INFO = 'INFO',
    12	  WARN = 'WARN',
    13	  ERROR = 'ERROR',
    14	}
    15	
    16	interface LogEntry {
    17	  timestamp: string;
    18	  level: LogLevel;
    19	  service: string;
    20	  message: string;
    21	  data?: Record<string, unknown>;
    22	}
    23	
    24	class Logger {
    25	  private minLevel: LogLevel;
    26	  private static readonly LEVEL_ORDER: LogLevel[] = [
    27	    LogLevel.DEBUG,
    28	    LogLevel.INFO,
    29	    LogLevel.WARN,
    30	    LogLevel.ERROR,
    31	  ];
    32	
    33	  constructor(minLevel: LogLevel = LogLevel.DEBUG) {
    34	    this.minLevel = minLevel;
    35	  }
    36	
    37	  private shouldLog(level: LogLevel): boolean {
    38	    const minIdx = Logger.LEVEL_ORDER.indexOf(this.minLevel);
    39	    const levelIdx = Logger.LEVEL_ORDER.indexOf(level);
    40	    return levelIdx >= minIdx;
    41	  }
    42	
    43	  private emit(entry: LogEntry): void {
    44	    const output = JSON.stringify(entry);
    45	    switch (entry.level) {
    46	      case LogLevel.ERROR:
    47	        console.error(output);
    48	        break;
    49	      case LogLevel.WARN:
    50	        console.warn(output);
    51	        break;
    52	      default:
    53	        console.log(output);
    54	        break;
    55	    }
    56	  }
    57	
    58	  private log(level: LogLevel, service: string, message: string, data?: Record<string, unknown>): void {
    59	    if (!this.shouldLog(level)) return;
    60	
    61	    const entry: LogEntry = {
    62	      timestamp: new Date().toISOString(),
    63	      level,
    64	      service,
    65	      message,
    66	    };
    67	
    68	    if (data && Object.keys(data).length > 0) {
    69	      entry.data = data;
    70	    }
    71	
    72	    this.emit(entry);
    73	  }
    74	
    75	  debug(service: string, message: string, data?: Record<string, unknown>): void {
    76	    this.log(LogLevel.DEBUG, service, message, data);
    77	  }
    78	
    79	  info(service: string, message: string, data?: Record<string, unknown>): void {
    80	    this.log(LogLevel.INFO, service, message, data);
    81	  }
    82	
    83	  warn(service: string, message: string, data?: Record<string, unknown>): void {
    84	    this.log(LogLevel.WARN, service, message, data);
    85	  }
    86	
    87	  error(service: string, message: string, data?: Record<string, unknown>): void {
    88	    this.log(LogLevel.ERROR, service, message, data);
    89	  }
    90	
    91	  /** Create a child logger scoped to a specific service. */
    92	  forService(serviceName: string): ServiceLogger {
    93	    return new ServiceLogger(this, serviceName);
    94	  }
    95	}
    96	
    97	class ServiceLogger {
    98	  private logger: Logger;
    99	  private serviceName: string;
   100	
   101	  constructor(logger: Logger, serviceName: string) {
   102	    this.logger = logger;
   103	    this.serviceName = serviceName;
   104	  }
   105	
   106	  debug(message: string, data?: Record<string, unknown>): void {
   107	    this.logger.debug(this.serviceName, message, data);
   108	  }
   109	
   110	  info(message: string, data?: Record<string, unknown>): void {
   111	    this.logger.info(this.serviceName, message, data);
   112	  }
