     1	import * as fs from 'fs';
     2	import * as path from 'path';
     3	import { v4 as uuidv4 } from 'uuid';
     4	import { Document } from '../shared/types';
     5	import { PersistenceService } from './persistence-service';
     6	import { logger } from './logger';
     7	
     8	const SERVICE = 'document-service';
     9	const DOCUMENTS_META = 'documents-meta.json';
    10	
    11	export class DocumentService {
    12	  private persistence: PersistenceService;
    13	
    14	  constructor(persistence: PersistenceService) {
    15	    this.persistence = persistence;
    16	  }
    17	
    18	  /** List all imported documents. */
    19	  listDocuments(): Document[] {
    20	    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
    21	    logger.debug(SERVICE, 'Listing documents', { count: docs?.length ?? 0 });
    22	    return docs ?? [];
    23	  }
    24	
    25	  /** Import a file from the given path. */
    26	  importDocument(filePath: string): Document {
    27	    if (!fs.existsSync(filePath)) {
    28	      logger.error(SERVICE, `File not found: ${filePath}`);
    29	      throw new Error(`File not found: ${filePath}`);
    30	    }
    31	
    32	    const filename = path.basename(filePath);
    33	    const content = fs.readFileSync(filePath, 'utf-8');
    34	    const stats = fs.statSync(filePath);
    35	
    36	    const doc: Document = {
    37	      id: uuidv4(),
    38	      title: filename.replace(/\.[^.]+$/, ''),
    39	      filename,
    40	      importedAt: new Date().toISOString(),
    41	      size: stats.size,
    42	      status: 'imported',
    43	    };
    44	
    45	    // Copy file to data directory
    46	    this.persistence.copyFileToDocuments(filePath, filename);
    47	
    48	    // Store content for indexing
    49	    this.persistence.writeText(`content/${doc.id}.txt`, content);
    50	
    51	    // Update metadata
    52	    const docs = this.listDocuments();
    53	    docs.push(doc);
    54	    this.persistence.writeJson(DOCUMENTS_META, docs);
    55	
    56	    logger.info(SERVICE, 'Document imported', {
    57	      documentId: doc.id,
    58	      filename: doc.filename,
    59	      size: doc.size,
    60	    });
    61	    return doc;
    62	  }
    63	
    64	  /** Get a single document by ID. */
    65	  getDocument(id: string): Document | null {
    66	    const docs = this.listDocuments();
    67	    return docs.find(d => d.id === id) ?? null;
    68	  }
    69	
    70	  /** Get the text content of a document. */
    71	  getDocumentContent(id: string): string | null {
    72	    return this.persistence.readText(`content/${id}.txt`);
    73	  }
    74	
    75	  /** Update a document's metadata. */
    76	  updateDocument(id: string, updates: Partial<Document>): Document | null {
    77	    const docs = this.listDocuments();
    78	    const index = docs.findIndex(d => d.id === id);
    79	    if (index === -1) return null;
    80	
    81	    docs[index] = { ...docs[index], ...updates };
    82	    this.persistence.writeJson(DOCUMENTS_META, docs);
    83	    logger.info(SERVICE, 'Document updated', { documentId: id, fields: Object.keys(updates) });
    84	    return docs[index];
    85	  }
    86	
    87	  /** Delete a document by ID. */
    88	  deleteDocument(id: string): boolean {
    89	    const docs = this.listDocuments();
    90	    const doc = docs.find(d => d.id === id);
    91	    if (!doc) return false;
    92	
    93	    this.persistence.deleteFromDocuments(doc.filename);
    94	
    95	    const updated = docs.filter(d => d.id !== id);
    96	    this.persistence.writeJson(DOCUMENTS_META, updated);
    97	    logger.info(SERVICE, 'Document deleted', { documentId: id, filename: doc.filename });
    98	    return true;
    99	  }
   100	}
=== src/services/indexing-service.ts
     1	import { v4 as uuidv4 } from 'uuid';
     2	import { Chunk, Document } from '../shared/types';
     3	import { PersistenceService } from './persistence-service';
     4	import { logger } from './logger';
     5	
     6	const SERVICE = 'indexing-service';
     7	const INDEX_META = 'index-meta.json';
     8	const CHUNKS_DIR = 'chunks';
     9	
    10	interface IndexStatus {
    11	  status: 'idle' | 'indexing' | 'ready' | 'error';
    12	  currentIndexed: number;
    13	  totalDocuments: number;
    14	  lastIndexed: string | null;
    15	}
    16	
    17	export class IndexingService {
    18	  private persistence: PersistenceService;
    19	
    20	  constructor(persistence: PersistenceService) {
    21	    this.persistence = persistence;
    22	  }
    23	
    24	  /** Start indexing documents. If documentId is provided, index only that document. */
    25	  async startIndexing(documentId?: string): Promise<IndexStatus> {
    26	    const status = this.getStatus();
    27	
    28	    if (documentId) {
    29	      const content = this.persistence.readText(`content/${documentId}.txt`);
    30	      if (!content) {
    31	        logger.error(SERVICE, `Content not found for document: ${documentId}`);
    32	        return { ...status, status: 'error' };
    33	      }
    34	      const chunks = this.chunkDocument(documentId, content);
    35	      this.persistence.writeJson(`${CHUNKS_DIR}/${documentId}.json`, chunks);
    36	      logger.info(SERVICE, 'Single document indexed', {
    37	        documentId,
    38	        chunkCount: chunks.length,
    39	      });
    40	      return this.getStatus();
    41	    }
    42	
    43	    const docsMeta = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
    44	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    45	
    46	    let indexedCount = 0;
    47	    for (const doc of docsMeta) {
    48	      if (chunksMeta[doc.id]) continue;
    49	
    50	      const content = this.persistence.readText(`content/${doc.id}.txt`);
    51	      if (!content) continue;
    52	
    53	      const chunks = this.chunkDocument(doc.id, content);
    54	      this.persistence.writeJson(`${CHUNKS_DIR}/${doc.id}.json`, chunks);
    55	      chunksMeta[doc.id] = chunks.map(c => c.id);
    56	      indexedCount++;
    57	      logger.info(SERVICE, 'Document indexed', {
    58	        documentId: doc.id,
    59	        chunkCount: chunks.length,
    60	      });
    61	    }
    62	
    63	    this.persistence.writeJson(INDEX_META, chunksMeta);
    64	    logger.info(SERVICE, 'Batch indexing complete', {
    65	      totalDocs: docsMeta.length,
    66	      newlyIndexed: indexedCount,
    67	    });
    68	    return this.getStatus();
    69	  }
    70	
    71	  /** Get current indexing status. */
    72	  getStatus(): IndexStatus {
    73	    const docs = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
    74	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    75	
    76	    const currentIndexed = Object.keys(chunksMeta).length;
    77	    const totalDocuments = docs.length;
    78	    const isReady = currentIndexed === totalDocuments && totalDocuments > 0;
    79	
    80	    return {
    81	      status: isReady ? 'ready' : currentIndexed > 0 ? 'indexing' : 'idle',
    82	      currentIndexed,
    83	      totalDocuments,
    84	      lastIndexed: new Date().toISOString(),
    85	    };
    86	  }
    87	
    88	  /** Get all chunks for a document. */
    89	  getChunksForDocument(documentId: string): Chunk[] {
    90	    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
    91	  }
    92	
    93	  /** Get all chunks across all documents. */
    94	  getAllChunks(): Chunk[] {
    95	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    96	    const allChunks: Chunk[] = [];
    97	
    98	    for (const docId of Object.keys(chunksMeta)) {
    99	      const chunks = this.getChunksForDocument(docId);
   100	      allChunks.push(...chunks);
   101	    }
   102	
   103	    return allChunks;
   104	  }
   105	
   106	  /** Split a document into chunks of ~500 characters at paragraph boundaries. */
   107	  private chunkDocument(documentId: string, content: string): Chunk[] {
   108	    const CHUNK_SIZE = 500;
   109	    const chunks: Chunk[] = [];
   110	
   111	    const paragraphs = content.split(/\n\s*\n/).filter(p => p.trim().length > 0);
   112	
   113	    let buffer = '';
   114	    let chunkIndex = 0;
   115	
   116	    for (const para of paragraphs) {
   117	      if (buffer.length + para.length > CHUNK_SIZE && buffer.length > 0) {
   118	        chunks.push(this.createChunk(documentId, chunkIndex++, buffer.trim()));
   119	        buffer = para;
   120	      } else {
   121	        buffer += (buffer ? '\n\n' : '') + para;
   122	      }
   123	    }
   124	
   125	    if (buffer.trim()) {
   126	      chunks.push(this.createChunk(documentId, chunkIndex, buffer.trim()));
   127	    }
   128	
   129	    return chunks;
   130	  }
   131	
   132	  private createChunk(documentId: string, index: number, content: string): Chunk {
   133	    return {
   134	      id: uuidv4(),
   135	      documentId,
   136	      content,
   137	      index,
   138	      metadata: {
   139	        charCount: String(content.length),
