    37	    answer: 'The meeting summary indicates that the team discussed implementing a retrieval-augmented generation pipeline. Key decisions included using local chunk storage and citation-based verification to ensure answer accuracy.',
    38	    excerpt: 'The team discussed implementing a retrieval-augmented generation pipeline',
    39	  },
    40	  {
    41	    keywords: ['logging', 'debug', 'observe', 'monitor'],
    42	    answer: 'The application uses structured JSON logging throughout all services. Each log entry includes a timestamp, log level, service name, and optional data payload. This enables runtime observability and debugging of the full document lifecycle.',
    43	    excerpt: 'The application uses structured JSON logging throughout all services',
    44	  },
    45	  {
    46	    keywords: ['feedback', 'rating', 'quality'],
    47	    answer: 'Users can provide positive or negative feedback on Q&A responses. Feedback is stored alongside the question and answer in a dedicated feedback log. This data can be used to improve answer quality over time.',
    48	    excerpt: 'Users can provide positive or negative feedback on Q&A responses',
    49	  },
    50	];
    51	
    52	export class QaService {
    53	  private persistence: PersistenceService;
    54	  private indexingService: IndexingService;
    55	
    56	  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
    57	    this.persistence = persistence;
    58	    this.indexingService = indexingService ?? new IndexingService(persistence);
    59	  }
    60	
    61	  /** Ask a question and get a grounded answer with citations. */
    62	  async ask(question: string): Promise<QAResponse> {
    63	    logger.info(SERVICE, 'Processing question', { question });
    64	    // Simulate processing delay
    65	    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 400));
    66	
    67	    const chunks = this.indexingService.getAllChunks();
    68	    const citations: Citation[] = [];
    69	
    70	    if (chunks.length > 0) {
    71	      // Find relevant chunks using keyword matching
    72	      const questionWords = question.toLowerCase().split(/\s+/).filter(w => w.length > 2);
    73	      const scored = chunks.map(chunk => {
    74	        const contentLower = chunk.content.toLowerCase();
    75	        const score = questionWords.reduce(
    76	          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
    77	          0
    78	        );
    79	        return { chunk, score };
    80	      });
    81	
    82	      // Take top 2 relevant chunks as citations
    83	      const relevant = scored
    84	        .filter(s => s.score > 0)
    85	        .sort((a, b) => b.score - a.score)
    86	        .slice(0, 2);
    87	
    88	      // Get document metadata for citations
    89	      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
    90	
    91	      for (const { chunk } of relevant) {
    92	        const doc = docs.find(d => d.id === chunk.documentId);
    93	        citations.push({
    94	          documentId: chunk.documentId,
    95	          documentTitle: doc?.title ?? 'Unknown Document',
    96	          chunkIndex: chunk.index,
    97	          excerpt: chunk.content.substring(0, 200),
    98	        });
    99	      }
   100	    }
   101	
   102	    // Generate answer from mock patterns or use fallback
   103	    const answer = this.generateAnswer(question, citations);
   104	
   105	    const response: QAResponse = {
   106	      answer,
   107	      citations,
   108	      confidence: citations.length > 0 ? 0.85 : 0.3,
   109	      timestamp: new Date().toISOString(),
   110	    };
   111	
   112	    // Save to history
   113	    this.saveToHistory(question, response);
   114	
   115	    logger.info(SERVICE, 'Answer generated', {
   116	      confidence: response.confidence,
   117	      citationCount: citations.length,
   118	    });
   119	    return response;
   120	  }
   121	
   122	  /** Get the Q&A history. */
   123	  getHistory(): QAHistory[] {
   124	    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
   125	  }
   126	
   127	  /** Clear the Q&A history. */
   128	  clearHistory(): void {
   129	    this.persistence.writeJson(QA_HISTORY_FILE, []);
   130	    logger.info(SERVICE, 'Q&A history cleared');
   131	  }
   132	
   133	  private generateAnswer(question: string, citations: Citation[]): string {
   134	    // Match against mock patterns
   135	    const questionLower = question.toLowerCase();
   136	    for (const pattern of MOCK_PATTERNS) {
   137	      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
   138	        if (citations.length > 0) {
   139	          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
   140	        }
   141	        return pattern.answer;
   142	      }
   143	    }
   144	
   145	    // Fallback answer
   146	    if (citations.length > 0) {
   147	      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
   148	    }
   149	
   150	    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
   151	  }
   152	
   153	  private saveToHistory(question: string, response: QAResponse): void {
   154	    const history = this.getHistory();
   155	    history.push({ question, response });
   156	    this.persistence.writeJson(QA_HISTORY_FILE, history);
   157	  }
   158	}
