import { useEffect, useState } from 'react';
import { FeedbackRating } from '../../shared/types';

interface Props {
  answerId: string;
  /** The rating already stored for this answer, if any. */
  rating?: FeedbackRating;
}

const baseStyle = {
  padding: '3px 10px',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '13px',
  color: '#e0e0e0',
} as const;

/** Helpful / not helpful buttons for one answer. The pressed button shows the stored rating. */
export function AnswerFeedback({ answerId, rating: initialRating }: Props) {
  const [rating, setRating] = useState<FeedbackRating | undefined>(initialRating);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => setRating(initialRating), [initialRating]);

  const submit = async (value: FeedbackRating) => {
    setSaving(true);
    setError(null);
    try {
      const entry = await window.knowledgeBase.feedback.submit(answerId, value);
      setRating(entry.rating);
    } catch (err) {
      console.error('Feedback failed:', err);
      setError('Could not save feedback');
    } finally {
      setSaving(false);
    }
  };

  const button = (value: FeedbackRating, label: string, icon: string, activeColor: string) => {
    const active = rating === value;
    return (
      <button
        type="button"
        aria-label={label}
        aria-pressed={active}
        title={label}
        disabled={saving}
        onClick={() => submit(value)}
        style={{
          ...baseStyle,
          background: active ? activeColor : 'transparent',
