import { beforeEach, describe, expect, it, vi } from 'vitest';
import * as path from 'path';
import { makeServices, quietLogs, SAMPLE_DOCS, tempDir } from './helpers';

beforeEach(() => {
  quietLogs();
  // QaService simulates 100-500ms latency with setTimeout; skip it.
  vi.spyOn(Math, 'random').mockReturnValue(0);
});

describe('answer ids', () => {
  it('every answer has a unique string id that is stored in history', async () => {
    const { qaService } = makeServices(tempDir());
    const a = await qaService.ask('How does indexing work?');
    const b = await qaService.ask('How does indexing work?');
    expect(typeof a.id).toBe('string');
    expect(a.id.length).toBeGreaterThan(0);
    expect(a.id).not.toBe(b.id);
    expect(qaService.getHistory().map(h => h.response.id)).toEqual([a.id, b.id]);
  });

  it('backfills stable ids for history saved before answers had ids', () => {
    const dir = tempDir();
    const { persistence, qaService } = makeServices(dir);
    persistence.writeJson('qa-history.json', [
      { question: 'old', response: { answer: 'x', citations: [], confidence: 0.3, timestamp: '2026-01-01T00:00:00.000Z' } },
    ]);
    const first = qaService.getHistory()[0].response.id;
    expect(typeof first).toBe('string');
    expect(makeServices(dir).qaService.getHistory()[0].response.id).toBe(first);
  });
});

describe('FeedbackService', () => {
  it('submit stores {answerId, rating, timestamp} and list returns it', async () => {
    const { qaService, feedbackService } = makeServices(tempDir());
    const answer = await qaService.ask('What about logging?');
    const entry = feedbackService.submit(answer.id, 'up');
    expect(entry).toEqual({ answerId: answer.id, rating: 'up', timestamp: expect.any(String) });
    expect(Number.isNaN(Date.parse(entry.timestamp))).toBe(false);
    expect(feedbackService.list()).toEqual([entry]);
  });

  it('keeps one rating per answer; rating again replaces it', async () => {
    const { qaService, feedbackService } = makeServices(tempDir());
    const a = await qaService.ask('first question');
    const b = await qaService.ask('second question');
    feedbackService.submit(a.id, 'up');
    feedbackService.submit(b.id, 'down');
    feedbackService.submit(a.id, 'down');
    const list = feedbackService.list();
    expect(list).toHaveLength(2);
    expect(list.find(f => f.answerId === a.id)?.rating).toBe('down');
    expect(list.find(f => f.answerId === b.id)?.rating).toBe('down');
  });

  it('rejects invalid ratings, empty ids and unknown answers without storing anything', async () => {
    const { qaService, feedbackService } = makeServices(tempDir());
    const a = await qaService.ask('question');
    expect(() => feedbackService.submit(a.id, 'meh')).toThrow(/rating/);
    expect(() => feedbackService.submit('', 'up')).toThrow(/answerId/);
    expect(() => feedbackService.submit(42, 'up')).toThrow(/answerId/);
    expect(() => feedbackService.submit('no-such-answer', 'up')).toThrow(/No answer/);
    expect(feedbackService.list()).toEqual([]);
  });

  it('ratings persist across a restart (new services on the same data dir)', async () => {
    const dir = tempDir();
    const before = makeServices(dir);
    before.documentService.importDocument(path.join(SAMPLE_DOCS, 'design-notes.md'));
    await before.indexingService.startIndexing();
    const answer = await before.qaService.ask('What is the architecture design?');
    before.feedbackService.submit(answer.id, 'down');

    const after = makeServices(dir);
    expect(after.feedbackService.list()).toEqual([
      { answerId: answer.id, rating: 'down', timestamp: expect.any(String) },
    ]);
  });
});
