// E2E for feature answer-feedback, against the built app (run `npm run build` first).
// Usage: node --experimental-websocket scripts/e2e/answer-feedback.mjs
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { withApp, pageHelpers, report } from './app-session.mjs';

const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-e2e-feedback-'));
const checks = [];
try {
  const first = await withApp({ dataDir }, async ({ evaluate, waitFor }) => {
    await evaluate(pageHelpers);
    const doc = path.resolve('data/sample-documents/design-notes.md');
    await evaluate(`window.knowledgeBase.documents.import(${JSON.stringify(doc)})`);
    await evaluate(`window.knowledgeBase.indexing.start()`);
    const a = await evaluate(`window.knowledgeBase.qa.ask('What is the architecture design?')`);
    const b = await evaluate(`window.knowledgeBase.qa.ask('What is the architecture design?')`);
    checks.push(['qa.ask returns a string id', typeof a.id === 'string' && a.id.length > 0, a.id]);
    checks.push(['ids are unique', a.id !== b.id]);
    const entry = await evaluate(`window.knowledgeBase.feedback.submit(${JSON.stringify(a.id)}, 'up')`);
    checks.push(['feedback.submit returns {answerId, rating, timestamp}',
      entry.answerId === a.id && entry.rating === 'up' && !Number.isNaN(Date.parse(entry.timestamp)), entry]);
    const bad = await evaluate(`window.knowledgeBase.feedback.submit(${JSON.stringify(a.id)}, 'meh').then(() => 'accepted', e => 'rejected')`);
    checks.push(['feedback.submit rejects an invalid rating', bad === 'rejected', bad]);

    // UI: ask through the question box, then rate through the button.
    await evaluate(`(() => { const i = document.querySelector('form input[type=text]'); __e2e.setInput(i, 'How does logging work?'); document.querySelector('form').requestSubmit(); return true; })()`);
    await waitFor(`__e2e.byLabel('Mark answer helpful').length > 0`);
    const buttons = await evaluate(`({ up: __e2e.byLabel('Mark answer helpful').length, down: __e2e.byLabel('Mark answer not helpful').length })`);
    checks.push(['UI answer renders both feedback buttons', buttons.up > 0 && buttons.down > 0, buttons]);
    await evaluate(`(() => { const btns = __e2e.byLabel('Mark answer not helpful'); btns[btns.length - 1].click(); return true; })()`);
    await waitFor(`(() => { const btns = __e2e.byLabel('Mark answer not helpful'); return btns[btns.length - 1].getAttribute('aria-pressed') === 'true'; })()`);
    const list = await evaluate(`window.knowledgeBase.feedback.list()`);
    const history = await evaluate(`window.knowledgeBase.qa.history()`);
    const uiAnswerId = history[history.length - 1].response.id;
    checks.push(['clicking the button stored a down rating for the UI answer',
      list.some((f) => f.answerId === uiAnswerId && f.rating === 'down'), list]);
    return { a, uiAnswerId };
  });

  // Restart the app on the same data dir.
  await withApp({ dataDir }, async ({ evaluate }) => {
    const list = await evaluate(`window.knowledgeBase.feedback.list()`);
    checks.push(['after restart feedback.list() still has both ratings',
      list.length === 2 &&
        list.some((f) => f.answerId === first.a.id && f.rating === 'up') &&
        list.some((f) => f.answerId === first.uiAnswerId && f.rating === 'down'), list]);
  });
} finally {
  fs.rmSync(dataDir, { recursive: true, force: true });
}
report('answer-feedback e2e', checks);
EOF
