import { useEffect, useRef, useState } from 'react';

interface Props {
  /** Called after the app data was reset, so the UI can drop its state. */
  onReset: () => void;
}

const buttonStyle = {
  padding: '6px 14px',
  border: '1px solid #1a1a4e',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '13px',
} as const;

/** "Reset all data" button. Nothing is deleted until the user confirms in the dialog. */
export function ResetDataButton({ onReset }: Props) {
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!confirming) return;
    cancelRef.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !busy) setConfirming(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [confirming, busy]);

  const confirm = async () => {
    setBusy(true);
    setError(null);
    try {
      await window.knowledgeBase.app.reset();
      setConfirming(false);
      onReset();
    } catch (err) {
      console.error('Reset failed:', err);
      setError('Reset failed. Your data may be partially deleted; try again.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <button
        type="button"
        aria-label="Reset all data"
        onClick={() => { setError(null); setConfirming(true); }}
        style={{ ...buttonStyle, background: '#5a1f2a', color: '#f0d0d0' }}
      >
        Reset
      </button>
      {confirming && (
        <div
          style={{
            position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100,
          }}
        >
          <div
            role="alertdialog"
            aria-modal="true"
            aria-labelledby="reset-dialog-title"
            aria-describedby="reset-dialog-desc"
            style={{
              background: '#16213e', border: '1px solid #0f3460', borderRadius: '8px',
              padding: '20px', width: '400px', maxWidth: '90vw',
            }}
          >
            <h2 id="reset-dialog-title" style={{ fontSize: '16px', marginBottom: '8px' }}>Reset all data?</h2>
            <p id="reset-dialog-desc" style={{ fontSize: '13px', color: '#b0b0c8', lineHeight: 1.5 }}>
              This permanently deletes every document, chunk, Q&amp;A exchange and feedback rating.
              It cannot be undone.
            </p>
            {error && <p role="alert" style={{ color: '#d9534f', fontSize: '12px', marginTop: '8px' }}>{error}</p>}
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px', marginTop: '16px' }}>
              <button
                ref={cancelRef}
                type="button"
                onClick={() => setConfirming(false)}
                disabled={busy}
                style={{ ...buttonStyle, background: '#0f3460', color: '#e0e0e0' }}
              >
                Cancel
              </button>
              <button
                type="button"
                aria-label="Confirm reset all data"
                onClick={confirm}
                disabled={busy}
                style={{ ...buttonStyle, background: '#d9534f', color: '#fff', border: 'none' }}
              >
                {busy ? 'Resetting…' : 'Delete everything'}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
EOF
