import { beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import { IPC_CHANNELS } from '../src/shared/types';
import { registerIpcHandlers, Services } from '../src/main/ipc-handlers';
import { makeServices, quietLogs, SAMPLE_DOCS, tempDir } from './helpers';

beforeEach(() => {
  quietLogs();
  vi.spyOn(Math, 'random').mockReturnValue(0);
});

/** Fills every store: documents, content, original copies, chunks, index, Q&A history, feedback. */
async function populate(services: ReturnType<typeof makeServices>) {
  for (const f of ['design-notes.md', 'meeting-summary.txt']) {
    services.documentService.importDocument(path.join(SAMPLE_DOCS, f));
  }
  await services.indexingService.startIndexing();
  const answer = await services.qaService.ask('What is the architecture design?');
  services.feedbackService.submit(answer.id, 'up');
}

function filesUnder(dir: string): string[] {
  return fs.readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter(e => e.isFile())
    .map(e => path.join(e.parentPath ?? (e as any).path, e.name));
}

describe('reset all data', () => {
  it('app:reset clears documents, chunks, Q&A history and feedback', async () => {
    const dir = tempDir();
    const services = makeServices(dir);
    await populate(services);
    expect(services.documentService.listDocuments()).toHaveLength(2);
