export type ConfidenceLevel = 'high' | 'medium' | 'low';

export interface ConfidenceDisplay {
  level: ConfidenceLevel;
  /** 0-100, rounded. */
  percent: number;
  label: string;
  color: string;
}

const COLORS: Record<ConfidenceLevel, string> = {
  high: '#5cb85c',
  medium: '#f0ad4e',
  low: '#d9534f',
};

/** Maps a 0-1 confidence score to what the UI shows. >= 0.7 high, >= 0.4 medium, else low. */
export function describeConfidence(confidence: number): ConfidenceDisplay {
  const clamped = Number.isFinite(confidence) ? Math.min(1, Math.max(0, confidence)) : 0;
  const level: ConfidenceLevel = clamped >= 0.7 ? 'high' : clamped >= 0.4 ? 'medium' : 'low';
  const percent = Math.round(clamped * 100);
  const name = level[0].toUpperCase() + level.slice(1);
  return { level, percent, label: `${name} confidence (${percent}%)`, color: COLORS[level] };
}
