cat > src/renderer/components/CitationList.tsx <<'EOF'
import { useId, useState } from 'react';
import { Citation } from '../../shared/types';

/** Citations for one answer. Each one expands to show the cited excerpt. */
export function CitationList({ citations }: { citations: Citation[] }) {
  if (citations.length === 0) {
    return <div style={{ fontSize: '11px', color: '#777' }}>No citations: no indexed passage matched this question.</div>;
  }
  return (
    <div style={{ fontSize: '12px' }}>
      <div style={{ color: '#8888bb', marginBottom: '4px' }}>Sources ({citations.length})</div>
      <ul style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '4px' }}>
        {citations.map((c, i) => (
          <CitationItem key={`${c.documentId}-${c.chunkIndex}-${i}`} citation={c} number={i + 1} />
        ))}
      </ul>
    </div>
  );
}

function CitationItem({ citation, number }: { citation: Citation; number: number }) {
  const [expanded, setExpanded] = useState(false);
  const excerptId = useId();
  return (
    <li data-citation style={{ borderLeft: '2px solid #533483', paddingLeft: '8px' }}>
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={excerptId}
        onClick={() => setExpanded(e => !e)}
        style={{
          background: 'none', border: 'none', color: '#b8b8e8', cursor: 'pointer',
          fontSize: '12px', padding: '2px 0', textAlign: 'left',
        }}
      >
        {expanded ? '▾' : '▸'} [{number}] {citation.documentTitle}, chunk {citation.chunkIndex}
      </button>
      {expanded && (
        <blockquote
          id={excerptId}
          data-citation-excerpt
          style={{
            margin: '4px 0 2px', padding: '8px 10px', background: '#141432', borderRadius: '4px',
            color: '#cfcfe8', lineHeight: 1.5, whiteSpace: 'pre-wrap',
          }}
        >
          {citation.excerpt}
        </blockquote>
      )}
    </li>
  );
}
