import { useEffect, useRef, useState } from 'react';
import { FeedbackRating, QAHistory } from '../../shared/types';
import { AnswerFeedback } from './AnswerFeedback';
import { CitationList } from './CitationList';
import { ConfidenceIndicator } from './ConfidenceIndicator';

interface Props {
  history: QAHistory[];
  /** Stored rating per answer id. */
  ratings: Record<string, FeedbackRating>;
  /** Question sent but not answered yet. */
  pendingQuestion?: string | null;
  error?: string | null;
  onClearHistory?: () => void;
}

const time = (iso: string) => new Date(iso).toLocaleString();

/**
 * The full Q&A history as a chat: question bubbles on the right, answers on the left,
 * each answer with its confidence, expandable citations and feedback buttons.
 */
export function ConversationHistory({ history, ratings, pendingQuestion, error, onClearHistory }: Props) {
  const endRef = useRef<HTMLDivElement>(null);
  const [confirmingClear, setConfirmingClear] = useState(false);

  useEffect(() => {
    endRef.current?.scrollIntoView?.({ block: 'end' });
  }, [history.length, pendingQuestion]);

  const empty = history.length === 0 && !pendingQuestion;

  return (
    <section aria-label="Conversation" style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', minHeight: '28px' }}>
        <h2 style={{ fontSize: '16px', fontWeight: 600 }}>Conversation</h2>
        {onClearHistory && history.length > 0 && (
          confirmingClear ? (
            <span style={{ display: 'flex', gap: '6px', alignItems: 'center', fontSize: '12px' }}>
              Clear all {history.length} exchanges?
              <button type="button" onClick={() => { setConfirmingClear(false); onClearHistory(); }} style={smallButton('#d9534f')}>
                Clear
              </button>
              <button type="button" onClick={() => setConfirmingClear(false)} style={smallButton('#0f3460')}>
                Cancel
              </button>
            </span>
          ) : (
            <button type="button" onClick={() => setConfirmingClear(true)} style={smallButton('#0f3460')}>
              Clear history
            </button>
          )
        )}
      </div>

      {empty && (
        <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
          No questions yet. Ask something about your documents below.
        </div>
      )}

      <ol style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '18px' }}>
        {history.map(item => (
          <li key={item.response.id} data-exchange={item.response.id} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <UserBubble text={item.question} />
            <article
              aria-label="Answer"
              data-answer-id={item.response.id}
              style={{ ...bubble, alignSelf: 'flex-start', background: '#1a1a3e', border: '1px solid #0f3460' }}
            >
              <div style={{ fontSize: '14px', lineHeight: 1.6 }}>{item.response.answer}</div>
              <div style={{ marginTop: '10px' }}>
                <ConfidenceIndicator confidence={item.response.confidence} />
              </div>
              <div style={{ marginTop: '8px' }}>
                <CitationList citations={item.response.citations} />
              </div>
              <div style={{ marginTop: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
                <AnswerFeedback answerId={item.response.id} rating={ratings[item.response.id]} />
                <time dateTime={item.response.timestamp} style={{ fontSize: '10px', color: '#666' }}>
                  {time(item.response.timestamp)}
                </time>
              </div>
            </article>
          </li>
        ))}
        {pendingQuestion && (
          <li style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <UserBubble text={pendingQuestion} />
            <div role="status" style={{ ...bubble, alignSelf: 'flex-start', background: '#1a1a3e', color: '#888', fontStyle: 'italic' }}>
              Searching your documents…
            </div>
          </li>
        )}
      </ol>

      {error && <div role="alert" style={{ color: '#d9534f', fontSize: '13px' }}>{error}</div>}
      <div ref={endRef} />
    </section>
  );
}

